  ],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": [
    "C03", "C05", "C09", "C41", "C43", "C49", "C55", "C59", "C61", "C71", "C73", "C76"
  ],
  "claims": [
    {
      "claim": "The supplied theophylline contexts report direct oral bioavailability values of 77–103% under fasted and fed conditions, all far above the 20% threshold.",
      "card_ids": ["C03", "C05", "C06", "C11", "C15", "C18", "C21", "C24", "C27"]
    },
    {
      "claim": "Paraxanthine, another xanthine, is rapidly and completely absorbed from the gastrointestinal tract with high bioavailability.",
      "card_ids": ["C09"]
    },
    {
      "claim": "Human absorption records show theophylline fraction absorbed 96–100%, caffeine 100%, and dyphylline (a 7-substituted theophylline) completely absorbed.",
      "card_ids": ["C41", "C42", "C43", "C46", "C47", "C49", "C51", "C52"]
    },
    {
      "claim": "Caco-2 and intestinal permeability records show caffeine and theophylline have high apparent permeability with near-unity efflux ratios, indicating high passive permeability and no significant gut-wall efflux for the xanthine core.",
      "card_ids": ["C55", "C56", "C59", "C61", "C63"]
    },
    {
      "claim": "L6 hepatic records show caffeine and theophylline are low hepatic extraction ratio compounds with stable clearance under various stress and impairment conditions, supporting low hepatic first-pass loss for the xanthine core.",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C73", "C74", "C75", "C76"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C73", "C74", "C75", "C76"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for doxofylline itself is present in the supplied cards.",
    "L6 hepatic records are for caffeine/theophylline/paraxanthine, not doxofylline; the dioxolane substituent may alter metabolic fate.",
    "No doxofylline-specific hepatic clearance or metabolic stability assay is supplied.",
    "L4/L5 absorption and permeability records are not direct systemic F measurements and lack an IV comparator.",
    "Some theophylline F records are formulation-specific (e.g., sustained-release) and may not match the query form.",
    "No doxofylline-specific gut-wall efflux or intestinal metabolism assay is supplied."
  ],
  "decision_summary": "L6 hepatic-clearance records show caffeine and theophylline are low hepatic extraction ratio xanthines with stable clearance under stress and impairment conditions, supporting low hepatic first-pass loss for the xanthine core and reinforcing the high prediction for doxofylline. No L6 record provides affirmative evidence for F < 20%. Prediction remains high; confidence remains high; evidence basis strengthened."
}

